ACTIONS = {"smiles2sdf", "sdf_to_gjf", "xyz_to_gjf"}

_MAX_SMILES_ITEMS = 32
_MAX_ROUTE_CHARS = 4096
_MAX_TITLE_CHARS = 200
_MAX_CHECKPOINT_CHARS = 200
_CHECKPOINT_PATTERN = re.compile(r"^[A-Za-z0-9_.-]+$")
_MEMORY_PATTERN = re.compile(r"(\d+(?:\.\d+)?)\s*(KB|MB|GB|TB)", re.I)
_CANONICAL_XYZ_COMMENT_PREFIX = "generated by ResearchChemBench"
_CANONICAL_XYZ_STATE_PATTERN = re.compile(
    r"generated by ResearchChemBench charge=([+-]?\d+) multiplicity=(\+?\d+)"
)
_XYZ_STATE_DECLARATION_PATTERN = re.compile(r"(?<!\S)(charge|multiplicity)=\S+")
_AUTHOR_PROVENANCE = {
    "upstream_repository": UPSTREAM_REPOSITORY,
    "upstream_commit": UPSTREAM_COMMIT,
    "adapter": "workspace_artifact_and_native_preflight_v1",
    "gaussian_execution": "not_requested",
}
_SDF_TO_GJF_DEFAULT_ROUTE = (
    "p UB3LYP/6-31+G(d,p) empiricaldispersion=gd3bj opt=(calcfc) freq "
    "stable=opt integral=ultrafine scrf=(smd,solvent=EthylEthanoate)"
)


def _validate_author_action_request(
    request: dict[str, Any],
    action_id: str,
    *,
    input_fields: tuple[str, ...],
) -> dict[str, Any]:
    """读取作者 Action 输入并拒绝额外科学字段；不修改文件，失败时抛出 ``ValueError``。"""

    inputs, method_spec, action_settings = request_parts(request)
    unexpected_inputs = sorted(set(inputs) - set(input_fields))
    if unexpected_inputs:
        raise ValueError(f"{action_id} does not accept input fields: {unexpected_inputs}")
    if method_spec:
        raise ValueError(f"{action_id} does not accept method_spec fields")
    unexpected_settings = sorted(set(action_settings) - {"timeout_seconds"})
    if unexpected_settings:
        raise ValueError(
            f"{action_id} does not accept action_settings fields: {unexpected_settings}"
        )
    return inputs


def _resolve_author_input_file(value: Any, suffix: str, field_name: str) -> Path:
    """解析工作区输入并核对后缀和普通文件属性；不写入源文件，失败时拒绝越界路径。"""

    path = resolve_input_file(value)
    if path.suffix.casefold() != suffix:
        raise ValueError(f"{field_name} must reference a {suffix} file")
    if path.is_symlink() or not path.is_file():
        raise ValueError(f"{field_name} must reference a regular workspace file")
    relative_workspace_path(path)
    return path


def _read_xyz_single_frame(
    path: Path, *, fix_atom_count_line: bool
) -> str:
    """读取并校验一个完整 XYZ frame，返回未修改的 comment 行。

    输入只能是工作区内的普通文件；函数不回写输入。它核对原子数、坐标行和尾部内容，
    拒绝空文件、截断 frame、多帧内容以及非有限坐标；``fix_atom_count_line`` 只允许
    兼容作者支持的、数值上为整数的小数原子数；原子数必须为正，不会改变源文件。
    """

    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except UnicodeDecodeError as exc:
        raise ValueError("xyz_frame_invalid: XYZ file must be UTF-8 text") from exc
    if len(lines) < 2:
        raise ValueError("xyz_frame_invalid: XYZ input must contain atom count and comment")

    atom_count_text = lines[0].strip()
    if re.fullmatch(r"\+?\d+", atom_count_text):
        atom_count = int(atom_count_text)
    elif fix_atom_count_line:
        try:
            numeric_count = float(atom_count_text)
        except (TypeError, ValueError) as exc:
            raise ValueError("xyz_frame_invalid: XYZ atom count must be a non-negative integer") from exc
        if not math.isfinite(numeric_count) or not numeric_count.is_integer():
            raise ValueError("xyz_frame_invalid: XYZ atom count must be a non-negative integer")
        atom_count = int(numeric_count)
    else:
        raise ValueError("xyz_frame_invalid: XYZ atom count must be an integer")
    if atom_count <= 0:
        raise ValueError("xyz_frame_invalid: XYZ frame must contain at least one atom")

    coordinate_start = 2
    coordinate_end = coordinate_start + atom_count
    if len(lines) < coordinate_end:
        raise ValueError(
            "xyz_frame_incomplete: XYZ input does not contain the declared coordinate rows"
        )
    for atom_index, line in enumerate(lines[coordinate_start:coordinate_end], start=1):
        fields = line.split()
        if len(fields) < 4:
            raise ValueError(
                f"xyz_coordinate_invalid: XYZ atom row {atom_index} requires element and three coordinates"
            )
        for coordinate in fields[1:4]:
            try:
                numeric_coordinate = float(coordinate)
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"xyz_coordinate_invalid: XYZ atom row {atom_index} has a non-numeric coordinate"
                ) from exc
            if not math.isfinite(numeric_coordinate):
                raise ValueError(
                    f"xyz_coordinate_non_finite: XYZ atom row {atom_index} has a non-finite coordinate"
                )

    trailing_content = [line for line in lines[coordinate_end:] if line.strip()]
    if trailing_content:
        raise ValueError(
            "xyz_frame_count_invalid: xyz_to_gjf requires exactly one complete XYZ frame"
        )
    return lines[1]


def _parse_canonical_xyz_state(comment: str) -> dict[str, int] | None:
    """严格解析 MiniChem ``write_xyz`` 的规范状态 comment。

    非规范 comment 不提供状态并返回 ``None``，从而保留作者原有默认值。以规范前缀开头
    但声明重复、缺失、顺序错误或数值非法的 comment 会明确失败，避免从任意文本猜测
    Gaussian 电荷或自旋多重度。
    """

    normalized = comment.strip()
    if not normalized.startswith(_CANONICAL_XYZ_COMMENT_PREFIX):
        return None
    declarations = _XYZ_STATE_DECLARATION_PATTERN.findall(normalized)
    if declarations.count("charge") != 1 or declarations.count("multiplicity") != 1:
        raise ValueError(
            "xyz_state_conflict: canonical XYZ comment must declare charge and multiplicity exactly once"
        )
    match = _CANONICAL_XYZ_STATE_PATTERN.fullmatch(normalized)
    if match is None:
        raise ValueError(
            "xyz_state_invalid: canonical XYZ comment has an invalid charge or multiplicity declaration"
        )
    charge = int(match.group(1))
    multiplicity = int(match.group(2))
    if multiplicity < 1:
        raise ValueError(
            "xyz_state_invalid: canonical XYZ multiplicity must be a positive integer"
        )
    return {"charge": charge, "multiplicity": multiplicity}


def _extract_bound_gaussian_code(value: Any) -> Any:
    """从输入的 route、ArtifactRef 或上一步 ActionResult 中递归读取 ``gaussian_code``。

    函数只读取并解包结果，不写入文件或修改输入；完整结果先进入 ``result``，再优先
    读取顶层字段，字段不存在时兼容读取 ``inline_scalars``。返回解析出的值，无法识别
    时原样返回，由调用方继续校验并以 ``ValueError`` 报告无效 route。
    """

    item = unwrap_artifact(value)
    if isinstance(item, dict):
        if isinstance(item.get("result"), (dict, str)):
            return _extract_bound_gaussian_code(item["result"])
        if "gaussian_code" in item:
            return _extract_bound_gaussian_code(item["gaussian_code"])
        if isinstance(item.get("inline_scalars"), (dict, str)):
            return _extract_bound_gaussian_code(item["inline_scalars"])
    return item


def _validate_author_route(value: Any, field_name: str) -> str:
    """校验将传给作者函数的单行 route；不写文件，失败时拒绝完整 deck 或控制字符。"""

    route = _extract_bound_gaussian_code(value)
    if not isinstance(route, str) or not route.strip():
        raise ValueError(f"{field_name} must resolve to a non-empty string")
    route = route.strip()
    if len(route) > _MAX_ROUTE_CHARS or any(ord(character) < 32 for character in route):
        raise ValueError(f"{field_name} must be one bounded line without control characters")
    if "--link1--" in route.casefold() or "%" in route:
        raise ValueError(f"{field_name} contains a forbidden deck/control marker")
    if any(character in route for character in ";|&<>`$\\"):
        raise ValueError(f"{field_name} contains a forbidden control character")
    return route


def _validate_author_text(value: Any, field_name: str, *, maximum: int) -> str:
    """校验作者单行文本参数并返回原文本；不写文件，失败时拒绝空值、超长或控制字符。"""

    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field_name} must be a non-empty string")
    text = value.strip()
    if len(text) > maximum or any(ord(character) < 32 for character in text):
        raise ValueError(f"{field_name} must be one bounded line without control characters")
    return text


def _validate_author_integer(
    value: Any, field_name: str, *, minimum: int, maximum: int
) -> int:
    """校验作者整数参数并返回整数；不产生副作用，失败时拒绝布尔、非整数或越界值。"""

    if isinstance(value, bool):
        raise ValueError(f"{field_name} must be an integer")
    try:
        parsed = int(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{field_name} must be an integer") from exc
    if isinstance(value, float) and not value.is_integer():
        raise ValueError(f"{field_name} must be an integer")
    if not minimum <= parsed <= maximum:
        raise ValueError(f"{field_name} must be between {minimum} and {maximum}")
    return parsed


def _validate_author_boolean(value: Any, field_name: str) -> bool:
    """校验作者布尔参数并返回原值；不产生副作用，失败时拒绝非布尔类型。"""

    if not isinstance(value, bool):
        raise ValueError(f"{field_name} must be a boolean")
    return value


def _memory_megabytes(value: str, field_name: str) -> int:
    """把 Gaussian 内存字符串换算为 MiB；不修改请求，失败时拒绝未知单位或过小内存。"""

    text = _validate_author_text(value, field_name, maximum=32)
    match = _MEMORY_PATTERN.fullmatch(text)
    if match is None:
        raise ValueError(f"{field_name} must be a value such as 4GB or 4096MB")
    factors = {"KB": 1 / 1024, "MB": 1, "GB": 1024, "TB": 1024 * 1024}
    memory_mb = int(float(match.group(1)) * factors[match.group(2).upper()])
    if memory_mb < 128:
        raise ValueError(f"{field_name} must provide at least 128 MB")
    return memory_mb


def _read_generated_deck_resources(path: Path) -> tuple[int, int, str]:
    """读取作者刚生成的 deck 并返回 CPU、内存和 route；不改写文件，失败时拒绝缺失或重复 route。"""

    lines = path.read_text(encoding="utf-8").splitlines()
    route_lines = [line.strip() for line in lines if line.lstrip().startswith("#")]
    if len(route_lines) != 1:
        raise ValueError("The generated Gaussian deck must contain exactly one route line")
    nprocshared = 1
    memory_mb = 1024
    for line in lines:
        lowered = line.casefold()
        if lowered.startswith("%nprocshared="):
            nprocshared = _validate_author_integer(
                line.split("=", 1)[1].strip(),
                "%nprocshared",
                minimum=1,
                maximum=4096,
            )
        elif lowered.startswith("%mem="):
            memory_mb = _memory_megabytes(line.split("=", 1)[1].strip(), "%mem")
    return nprocshared, memory_mb, route_lines[0]


def _preflight_author_gaussian_deck(path: Path) -> dict[str, Any]:
    """在原输出文件上补齐坐标分隔空行并执行 Gaussian native 预检。

    输入是作者刚写入的工作区 GJF 文件；函数会在该文件自身末尾确保最终坐标后有
    一个空行，再用同一路径构造 native 请求并只读校验。函数可能改写这个新生成的
    输出文件，但不会创建旁路 ``native_preflight.gjf`` 或修改作者输入文件；预检失败
    时向调用方抛出验证异常。
    """

    nprocshared, memory_mb, _route = _read_generated_deck_resources(path)
    # 格式 Action 只生成输入文件，不按 deck 指令占用 Gaussian 计算资源。
    # 实际提交 native Gaussian 时仍会按这些指令重新核对执行预算。
    # 作者工具可能只写一个换行；native validator 要求坐标后存在空行，包装层把
    # 规范化直接落到最终交付文件，确保下游拿到的同一个 Artifact 可再次校验。
    deck_text = path.read_text(encoding="utf-8")
    if not deck_text.endswith("\n\n"):
        path.write_text(deck_text.rstrip("\n") + "\n\n", encoding="utf-8")
    native_request = NativeJobRequest(
        software_id="gaussian",
        executable="g16",
        staged_inputs=[
            {
                "source_path": relative_workspace_path(path),
                "target_path": "inputs/generated.gjf",
            }
        ],
        stdin_target="inputs/generated.gjf",
        resource_limits={
            "cpu_cores": nprocshared,
            "memory_mb": memory_mb,
            "gpu_count": 0,
        },
        calculation_intent="other",
    )
    return _validate_gaussian_input_deck(native_request)


def _read_author_sdf_record_counts(path: Path) -> tuple[int, int]:
    """读取输入 SDF 的记录槽位总数和可解析分子数。

    函数通过 RDKit 只读扫描文件，不创建或修改文件；返回 ``(总记录槽位数，
    有效记录数)``。输入为空、不可读或扫描触发 ``OSError`` 时返回 ``(0, 0)``，不向
    调用方抛出该文件读取错误。
    """

    from rdkit import Chem

    try:
        if path.stat().st_size == 0:
            return 0, 0
        supplier = Chem.SDMolSupplier(str(path), removeHs=False)
        total_record_count = len(supplier)
        valid_record_count = sum(molecule is not None for molecule in supplier)
        return total_record_count, valid_record_count
    except OSError:
        return 0, 0


def _classify_smiles_failure(messages: list[str]) -> dict[str, str]:
    """把一个作者 SMILES 项目的输出消息转换为稳定错误对象。

    输入是该项目捕获的文本消息；函数只分类和拼接消息，不产生副作用，返回包含
    ``code`` 与 ``message`` 的字典。没有消息时使用通用转换失败说明，不抛出异常。
    """

    message = "; ".join(messages) if messages else "SMILES conversion did not produce one valid SDF record"
    if any(item.startswith("Failed to parse SMILES:") for item in messages):
        code = "smiles_parse_failed"
    elif any(item.startswith("3D embedding failed for SMILES:") for item in messages):
        code = "smiles_embedding_failed"
    else:
        code = "smiles_conversion_failed"
    return {"code": code, "message": message}


def _build_smiles_failure_item(
    *,
    item_id: str,
    input_index: int,
    smiles: str,
    messages: list[str],
) -> dict[str, Any]:
    """构造一个 SMILES 项目的失败事实。

    输入是稳定项目标识、输入位置、原始 SMILES 和作者消息；函数只组装字段，不写文件，
    返回含 ``item_id``、``input_index``、``smiles``、``status`` 和结构化 ``error`` 的
    字典。消息分类失败不会抛出异常，也不会主动附加异常堆栈或本地路径。
    """

    return {
        "item_id": item_id,
        "input_index": input_index,
        "smiles": smiles,
        "status": "failed",
        "error": _classify_smiles_failure(messages),
    }


def _build_smiles_conversion_failure(
    result: dict[str, Any], messages: list[str]
) -> dict[str, Any]:
    """为没有任何成功记录的批次构造结构化失败结果。

    输入是已汇总的批次结果和作者消息；函数不登记、不创建或返回空 SDF Artifact，
    返回状态为 ``failed``、错误码为 ``no_molecules_written`` 的结果。该构造函数本身
    不抛出批次失败异常，调用方可直接将返回值交给服务层。
    """

    failure = failed(
        "smiles2sdf did not write any valid molecule records",
        code="no_molecules_written",
    )
    failure.update(
        {
            "result": result,
            "artifact_files": [],
            "backend_version": module_version("rdkit"),
            "warnings": messages,
            "provenance": {
                **_AUTHOR_PROVENANCE,
                "upstream_function": "smiles_to_sdf",
            },
        }
    )
    return failure


def _convert_smiles_with_author_tool(request: dict[str, Any]) -> dict[str, Any]:
    """按请求逐项调用作者 SMILES 转换并登记批次产物。

    输入是只含 ``smiles_list`` 的 Action 请求；函数最多处理 32 项，为每项写入单记录
    SDF，再按成功输入顺序写入合并 SDF，并在返回的 Artifact 清单中提供成员文件结果指针
    供服务层登记。函数有文件写入副作用，返回全成功、部分成功或全失败的结构化结果；
    请求字段非法时抛出 ``ValueError``，单项作者失败进入 ``items``，全部失败返回
    ``failed`` 而不返回空 primary 文件。
    """

    inputs = _validate_author_action_request(
        request, "smiles2sdf", input_fields=("smiles_list",)
    )
    smiles_value = inputs.get("smiles_list")
    if isinstance(smiles_value, (list, tuple)) and smiles_value:
        smiles_values = list(smiles_value)
    else:
        raise ValueError("inputs.smiles_list must be a non-empty list")
    if any(not isinstance(value, str) for value in smiles_values):
        raise ValueError("Every inputs.smiles_list item must be a string")
    if len(smiles_values) > _MAX_SMILES_ITEMS:
        raise ValueError(
            f"inputs.smiles_list must contain at most {_MAX_SMILES_ITEMS} items"
        )

    directory = output_directory("smiles2sdf", "format_conversion")
    output_path = directory / "result.sdf"
    messages: list[str] = []
    items: list[dict[str, Any]] = []
    successful_records: list[dict[str, Any]] = []
    successful_member_paths: list[Path] = []

    for input_index, smiles in enumerate(smiles_values):
        item_id = f"smiles_{input_index + 1:04d}"
        member_path = directory / f"{item_id}.sdf"
        printed = StringIO()
        with redirect_stdout(printed):
            returned_path = author_smiles2sdf.smiles_to_sdf(
                [smiles], str(member_path)
            )
        item_messages = [
            line for line in printed.getvalue().splitlines() if line.strip()
        ]
        messages.extend(item_messages)
        if Path(returned_path) != member_path or not member_path.is_file():
            items.append(
                _build_smiles_failure_item(
                    item_id=item_id,
                    input_index=input_index,
                    smiles=smiles,
                    messages=item_messages
                    or ["Author smiles_to_sdf did not return its assigned output file"],
                )
            )
            member_path.unlink(missing_ok=True)
            continue

        total_record_count, valid_record_count = _read_author_sdf_record_counts(
            member_path
        )
        if total_record_count != 1 or valid_record_count != 1:
            failure_messages = item_messages or [
                "SDF member contains "
                f"{total_record_count} record slots and {valid_record_count} valid records; "
                "exactly one of each is required"
            ]
            items.append(
                _build_smiles_failure_item(
                    item_id=item_id,
                    input_index=input_index,
                    smiles=smiles,
                    messages=failure_messages,
                )
            )
            member_path.unlink(missing_ok=True)
            continue

        items.append(
            {
                "item_id": item_id,
                "input_index": input_index,
                "smiles": smiles,
                "status": "success",
            }
        )
        successful_member_paths.append(member_path)
        successful_records.append(
            {
                "item_id": item_id,
                "input_index": input_index,
                "sdf_artifact": None,
            }
        )

    failed_item_count = len(smiles_values) - len(successful_records)
    result = {
        "input_count": len(smiles_values),
        "molecules_written": len(successful_records),
        "failed_item_count": failed_item_count,
        "messages": messages,
        "items": items,
        "successful_records": successful_records,
    }
    if not successful_member_paths:
        return _build_smiles_conversion_failure(result, messages)

    output_path.write_bytes(
        b"".join(member_path.read_bytes() for member_path in successful_member_paths)
    )
    artifact_files = [
        {
            "path": relative_workspace_path(output_path),
            "semantic_type": "SDFFile",
            "media_type": "chemical/x-mdl-sd",
        }
    ]
    artifact_files.extend(
        {
            "path": relative_workspace_path(member_path),
            "semantic_type": "SDFRecordFile",
            "media_type": "chemical/x-mdl-sd",
            "result_pointer": f"/successful_records/{index}/sdf_artifact",
        }
        for index, member_path in enumerate(successful_member_paths)
    )
    result = {
        "success": True,
        "output_sdf_path": relative_workspace_path(output_path),
        "input_count": len(smiles_values),
        "molecules_written": len(successful_records),
        "failed_item_count": failed_item_count,
        "messages": messages,
        "items": items,
        "successful_records": successful_records,
    }
    result_builder = partial_success if failed_item_count else success
    return result_builder(
        result,
        artifact_files=artifact_files,
        backend_version=module_version("rdkit"),
        provenance={**_AUTHOR_PROVENANCE, "upstream_function": "smiles_to_sdf"},
        warnings=messages,
    )


def _convert_sdf_with_author_tool(request: dict[str, Any]) -> dict[str, Any]:
    """调用作者 ``sdf_to_gjf`` 并预检新 deck；只写新输出，不运行 Gaussian 或改写输入。"""

    inputs = _validate_author_action_request(
        request,
        "sdf_to_gjf",
        input_fields=("sdf_path", "route_parameters", "title", "nprocshared", "mem"),
    )
    input_path = _resolve_author_input_file(
        inputs["sdf_path"], ".sdf", "inputs.sdf_path"
    )
    total_record_count, valid_record_count = _read_author_sdf_record_counts(input_path)
    if total_record_count != 1 or valid_record_count != 1:
        failure = failed(
            "sdf_to_gjf requires exactly one valid SDF record",
            code="sdf_record_count_invalid",
        )
        failure["result"] = {
            "input_sdf_path": relative_workspace_path(input_path),
            "total_record_count": total_record_count,
            "valid_record_count": valid_record_count,
            "expected_record_count": 1,
        }
        failure["artifact_files"] = []
        return failure
    kwargs: dict[str, Any] = {}
    if "route_parameters" in inputs:
        kwargs["route_parameters"] = _validate_author_route(
            inputs["route_parameters"], "inputs.route_parameters"
        )
    else:
        kwargs["route_parameters"] = _SDF_TO_GJF_DEFAULT_ROUTE
    if "title" in inputs:
        kwargs["title"] = _validate_author_text(
            inputs["title"], "inputs.title", maximum=_MAX_TITLE_CHARS
        )
    policy = gaussian_resource_policy()
    kwargs["nprocshared"] = policy.cpu_cores
    kwargs["mem"] = f"{policy.memory_mb}MB"

    directory = output_directory("sdf_to_gjf", "format_conversion")
    output_path = directory / "result.gjf"
    returned_path = author_sdf2gjf.sdf_to_gjf(
        str(input_path), str(output_path), **kwargs
    )
    if Path(returned_path) != output_path or not output_path.is_file():
        raise RuntimeError("作者 sdf_to_gjf 未返回 MCP 分配的输出文件")
    normalization_applied = not output_path.read_text(encoding="utf-8").endswith("\n\n")
    validation = _preflight_author_gaussian_deck(output_path)
    _nprocshared, _memory_mb, route = _read_generated_deck_resources(output_path)
    result = {
        "success": True,
        "input_sdf_path": relative_workspace_path(input_path),
        "output_gjf_path": relative_workspace_path(output_path),
        "route_section": route,
        "native_preflight": validation,
        "native_preflight_ready": True,
    }
    return success(
        result,
        artifact_files=[
            {
                "path": relative_workspace_path(output_path),
                "semantic_type": "GaussianInputDeck",
                "media_type": "chemical/x-gaussian-input",
            }
        ],
        backend_version=module_version("rdkit"),
        provenance={
            **_AUTHOR_PROVENANCE,
            "upstream_function": "sdf_to_gjf",
            "wrapper_normalization": {
                "gaussian_coordinate_separator": "final_blank_line",
                "applied": normalization_applied,
                "target": "same_output_artifact",
            },
        },
    )


def _convert_xyz_with_author_tool(request: dict[str, Any]) -> dict[str, Any]:
    """调用作者 ``xyz_to_gjf`` 并预检新 deck；只写新输出，明确禁止作者的输入回写选项。"""

    fields = (
        "input_xyz_path",
        "route_section",
        "charge",
        "multiplicity",
        "title",
        "chk_file",
        # 保留旧请求兼容字段；其值不会参与生成，始终由服务策略覆盖。
        "nprocshared",
        "mem",
        "fix_atom_count_line",
        "write_back_fixed_xyz",
    )
    inputs = _validate_author_action_request(
        request, "xyz_to_gjf", input_fields=fields
    )
    input_path = _resolve_author_input_file(
        inputs["input_xyz_path"], ".xyz", "inputs.input_xyz_path"
    )
    kwargs: dict[str, Any] = {}
    fix_atom_count_line = True
    if "fix_atom_count_line" in inputs:
        fix_atom_count_line = _validate_author_boolean(
            inputs["fix_atom_count_line"], "inputs.fix_atom_count_line"
        )
        kwargs["fix_atom_count_line"] = fix_atom_count_line
    comment = _read_xyz_single_frame(
        input_path, fix_atom_count_line=fix_atom_count_line
    )
    canonical_state = _parse_canonical_xyz_state(comment)
    if "route_section" in inputs:
        kwargs["route_section"] = _validate_author_route(
            inputs["route_section"], "inputs.route_section"
        )
    for name, minimum, maximum in (
        ("charge", -100, 100),
        ("multiplicity", 1, 100),
    ):
        if name in inputs and inputs[name] is not None:
            kwargs[name] = _validate_author_integer(
                inputs[name], f"inputs.{name}", minimum=minimum, maximum=maximum
            )
        elif canonical_state is not None and name in canonical_state:
            kwargs[name] = _validate_author_integer(
                canonical_state[name],
                f"canonical XYZ {name}",
                minimum=minimum,
                maximum=maximum,
            )
    if "title" in inputs:
        kwargs["title"] = _validate_author_text(
            inputs["title"], "inputs.title", maximum=_MAX_TITLE_CHARS
        )
    if "chk_file" in inputs and inputs["chk_file"] is not None:
        checkpoint = _validate_author_text(
            inputs["chk_file"],
            "inputs.chk_file",
            maximum=_MAX_CHECKPOINT_CHARS,
        )
        if checkpoint in {".", ".."} or not _CHECKPOINT_PATTERN.fullmatch(checkpoint):
            raise ValueError("inputs.chk_file must be a filename, not a path")
        kwargs["chk_file"] = checkpoint
    policy = gaussian_resource_policy()
    kwargs["nprocshared"] = policy.cpu_cores
    kwargs["mem"] = f"{policy.memory_mb}MB"
    if "write_back_fixed_xyz" in inputs:
        write_back = _validate_author_boolean(
            inputs["write_back_fixed_xyz"], "inputs.write_back_fixed_xyz"
        )
        if write_back:
            raise ValueError(
                "inputs.write_back_fixed_xyz must be false because MCP cannot rewrite input artifacts"
            )
        kwargs["write_back_fixed_xyz"] = False

    directory = output_directory("xyz_to_gjf", "format_conversion")
    output_path = directory / "result.gjf"
    author_result = author_xyz2gjf.xyz_to_gjf(
        str(input_path), str(output_path), **kwargs
    )
    if not author_result.get("success") or not output_path.is_file():
        raise RuntimeError("作者 xyz_to_gjf 未能生成 Gaussian 输入文件")
    normalization_applied = not output_path.read_text(encoding="utf-8").endswith("\n\n")
    validation = _preflight_author_gaussian_deck(output_path)
    result = {
        **author_result,
        "input_xyz_path": relative_workspace_path(input_path),
        "output_gjf_path": relative_workspace_path(output_path),
        "native_preflight": validation,
        "native_preflight_ready": True,
    }
    return success(
        result,
        artifact_files=[
            {
                "path": relative_workspace_path(output_path),
                "semantic_type": "GaussianInputDeck",
                "media_type": "chemical/x-gaussian-input",
            }
        ],
        backend_version="arche_author_xyz2gjf_" + UPSTREAM_COMMIT[:8],
        provenance={
            **_AUTHOR_PROVENANCE,
            "upstream_function": "xyz_to_gjf",
            "wrapper_normalization": {
                "gaussian_coordinate_separator": "final_blank_line",
                "applied": normalization_applied,
                "target": "same_output_artifact",
            },
        },
    )


def execute(action_id: str, backend_id: str, request: dict[str, Any]) -> dict[str, Any]:
    """执行一个作者格式工具并返回 MCP 结果；只允许 ``format_conversion`` 后端。"""

    if backend_id == "format_conversion" and action_id == "smiles2sdf":
        return _convert_smiles_with_author_tool(request)
    if backend_id == "format_conversion" and action_id == "sdf_to_gjf":
        return _convert_sdf_with_author_tool(request)
    if backend_id == "format_conversion" and action_id == "xyz_to_gjf":
        return _convert_xyz_with_author_tool(request)
    return unsupported(
        f"Unsupported author format action/backend combination: {action_id}/{backend_id}"
    )


__all__ = ["ACTIONS", "execute"]
